import clsx from 'clsx'
import type { MouseEventHandler, PropsWithChildren } from 'react'
import React, { useEffect, useRef, useState } from 'react'
import Alert from '../Alert/Alert'
import { AriaLiveRole } from '../utilities/aria'
import createDisposables from '../utilities/createDisposables'

/**
 * This is the same value as the snackbar-out animation in utilities.css, keeping them
 * the same is necessary to prvent removing the element from the DOM before it's done animating
 */
const EXIT_DURATION = 200

export interface SnackbarProps {
  /**
   * The anchor position of the snackbar on the screen
   */
  anchorOrigin: AnchorOrigin
  /**
   * The number of milliseconds to wait before automatically hiding the snackbar
   */
  autoHideDuration?: number
  /**
   * Custom icon to display as a start adornment of the snackbar. If not provided, a default icon based on the severity will be used
   */
  icon?: JSX.Element | null
  /**
   * Called once the snackbar has finished hiding itself after `autoHideDuration`
   * elapses. It is not called when the snackbar is closed via the `open` prop, as
   * the consumer already knows about that. Use it to sync the state driving `open`,
   * otherwise the snackbar cannot be reopened
   */
  onClose?: () => void
  /**
   * Whether the snackbar is currently open/visible
   * @default true
   */
  open?: boolean
  /**
   * [ARIA live region](https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Guides/Live_regions) role for accessibility.
   * Use `alert` for important, time-sensitive information, or `status` for advisory information
   * @default AriaLiveRole.Alert
   */
  role?: AriaLiveRole.Alert | AriaLiveRole.Status
  /**
   * The severity level that determines the color scheme and default icon
   * @default 'success'
   */
  severity?: Severity
}

type Severity = 'error' | 'info' | 'neutral' | 'success' | 'warning'

type HorizontalAnchorOrigin = 'center' | 'left' | 'right'

type VerticalAnchorOrigin = 'bottom' | 'center' | 'top'

type AnchorOrigin = {
  horizontal: HorizontalAnchorOrigin
  vertical: VerticalAnchorOrigin
}

function Snackbar({
  anchorOrigin: { horizontal, vertical },
  autoHideDuration,
  children,
  icon = null,
  onClose,
  open = true,
  role = AriaLiveRole.Alert,
  severity = 'success',
}: PropsWithChildren<SnackbarProps>): JSX.Element | null {
  const [shouldRender, setShouldRender] = useState(() => open)
  const [visible, setVisible] = useState(() => open)

  const onCloseRef = useRef(onClose)

  useEffect(() => {
    onCloseRef.current = onClose
  })

  useEffect(() => {
    const disposables = createDisposables()

    if (open) {
      setShouldRender(true)
      setVisible(true)
    } else {
      setVisible(false)
      disposables.setTimeout(() => setShouldRender(false), EXIT_DURATION)
    }

    return () => disposables.dispose()
  }, [open])

  // Handle auto-hiding behaviour
  useEffect(() => {
    if (!open || autoHideDuration === undefined) {
      return
    }

    const disposables = createDisposables()

    disposables.setTimeout(() => setVisible(false), autoHideDuration)
    disposables.setTimeout(() => {
      setShouldRender(false)
      onCloseRef.current?.()
    }, autoHideDuration + EXIT_DURATION)

    return () => disposables.dispose()
  }, [autoHideDuration, open])

  return shouldRender ? (
    <div
      className={clsx(
        'snackbar fixed flex shadow-6 rounded-md w-full max-w-xs z-9999',
        horizontal === 'left'
          ? 'left-0 ml-4 md:ml-8'
          : horizontal === 'right'
          ? 'right-0 mr-4 md:mr-8'
          : 'left-half',
        vertical === 'bottom'
          ? 'bottom-0 mb-4 md:mb-8'
          : vertical === 'top'
          ? 'top-0 mt-4 md:mt-8'
          : 'top-half',
      )}
      data-entering={visible || undefined}
      data-exiting={!visible || undefined}
      data-placement={vertical}
    >
      <Alert icon={icon} role={role} severity={severity}>
        {children}
      </Alert>
    </div>
  ) : null
}

function Content({
  children,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  return <Alert.Content>{children}</Alert.Content>
}

function Description({
  children,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  return <Alert.Description>{children}</Alert.Description>
}

function Title({
  children,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  return <Alert.Title>{children}</Alert.Title>
}

function Actions({
  children,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  return <Alert.Actions>{children}</Alert.Actions>
}

interface ButtonProps {
  /**
   * Custom data attributes to be added to the button element
   */
  dataSet?: Record<string, string | undefined>
  onClick?: MouseEventHandler<HTMLButtonElement>
}

function Button({
  children,
  dataSet,
  onClick,
}: PropsWithChildren<ButtonProps>): JSX.Element {
  return (
    <Alert.Button dataSet={dataSet} onClick={onClick}>
      {children}
    </Alert.Button>
  )
}

Snackbar.Actions = Actions
Snackbar.Button = Button
Snackbar.Content = Content
Snackbar.Description = Description
Snackbar.Title = Title

export default Snackbar
