function withMinHeight(minHeight: string) {
  const decorator = (Story: React.FC): JSX.Element => (
    <div style={{ minHeight }}>
      <Story />
    </div>
  )

  decorator.displayName = 'MinHeightDecorator'

  return decorator
}

function Template(
  args: SnackbarProps & {
    actionLabels: string[]
    description: string
    icon?: typeof SvgIcon
    role: string
    title: string
  },
): JSX.Element {
  const Icon = args.icon

  return (
    <Snackbar
      anchorOrigin={args.anchorOrigin}
      autoHideDuration={args.autoHideDuration}
      icon={Icon ? <Icon /> : null}
      open={args.open}
      role={args.role}
      severity={args.severity}
    >
      <Snackbar.Content>
        {args.title ? <Snackbar.Title>{args.title}</Snackbar.Title> : null}
        <Snackbar.Description>{args.description}</Snackbar.Description>
      </Snackbar.Content>
      {args.actionLabels.length ? (
        <Snackbar.Actions>
          {args.actionLabels.map((label) => (
            <Snackbar.Button key={label}>{label}</Snackbar.Button>
          ))}
        </Snackbar.Actions>
      ) : null}
    </Snackbar>
  )
}

export const Default = {
  decorators: [withMinHeight('100px')],
  render: Template,
}

