const MAX_AUTO_HIDE_DURATION = 8_500

export function Autohide(): JSX.Element {
  const [show, setShow] = useState(true)
  const hideShackbarsRef = useRef<ReturnType<typeof setTimeout>>()

  const resetStateWhenSnackbarHidden = () => {
    setShow(false)
  }

  const handleShow = (): void => {
    setShow(true)
    hideShackbarsRef.current = setTimeout(
      resetStateWhenSnackbarHidden,
      MAX_AUTO_HIDE_DURATION,
    )
  }

  useEffect(() => {
    hideShackbarsRef.current = setTimeout(
      resetStateWhenSnackbarHidden,
      MAX_AUTO_HIDE_DURATION,
    )

    return () => clearTimeout(hideShackbarsRef.current)
  }, [])

  return show ? (
    <>
      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'top' }}
        autoHideDuration={1000}
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Left</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'center', vertical: 'top' }}
        autoHideDuration={2000}
        severity="info"
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Middle</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
        autoHideDuration={3000}
        severity="warning"
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Right</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'center' }}
        autoHideDuration={4000}
        severity="error"
      >
        <Snackbar.Content>
          <Snackbar.Description>Left Middle</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'center' }}
        autoHideDuration={5000}
      >
        <Snackbar.Content>
          <Snackbar.Description>Right Middle</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'bottom' }}
        autoHideDuration={6000}
        severity="info"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Left</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'center', vertical: 'bottom' }}
        autoHideDuration={7000}
        severity="warning"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Middle</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        autoHideDuration={8000}
        severity="error"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Right</Snackbar.Description>
        </Snackbar.Content>
      </Snackbar>
    </>
  ) : (
    <Button color="primary" onClick={handleShow}>
      Show Snackbars
    </Button>
  )
}

Autohide.decorators = [withMinHeight('400px')]

export function ControlledDismiss(): JSX.Element {
  const [state, setState] = useState(() => ({
    bottomLeft: true,
    bottomMiddle: true,
    bottomRight: true,
    leftMiddle: true,
    rightMiddle: true,
    topLeft: true,
    topMiddle: true,
    topRight: true,
  }))

  return (
    <>
      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'top' }}
        open={state.topLeft}
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Left</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, topLeft: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'center', vertical: 'top' }}
        open={state.topMiddle}
        severity="info"
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Middle</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, topMiddle: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
        open={state.topRight}
        severity="warning"
      >
        <Snackbar.Content>
          <Snackbar.Description>Top Right</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, topRight: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'center' }}
        open={state.leftMiddle}
        severity="error"
      >
        <Snackbar.Content>
          <Snackbar.Description>Left Middle</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, leftMiddle: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'center' }}
        open={state.rightMiddle}
      >
        <Snackbar.Content>
          <Snackbar.Description>Right Middle</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, rightMiddle: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'left', vertical: 'bottom' }}
        open={state.bottomLeft}
        severity="info"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Left</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, bottomLeft: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'center', vertical: 'bottom' }}
        open={state.bottomMiddle}
        severity="warning"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Middle</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, bottomMiddle: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>

      <Snackbar
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        open={state.bottomRight}
        severity="error"
      >
        <Snackbar.Content>
          <Snackbar.Description>Bottom Right</Snackbar.Description>
        </Snackbar.Content>
        <Snackbar.Actions>
          <Snackbar.Button
            onClick={() => {
              setState((prevState) => ({ ...prevState, bottomRight: false }))
            }}
          >
            Dismiss
          </Snackbar.Button>
        </Snackbar.Actions>
      </Snackbar>
    </>
  )
}

